const CONFIG = { teamEmail: 'team@your-domain.example', website: 'https://your-domain.example', whatsapp: '234XXXXXXXXXX', sheetId: 'YOUR_GOOGLE_SHEET_ID' };
const SHEET_GIDS = { Rent: '0', Buy: '1705566378', Invest: '1194300972' };
const PROPERTY_TYPES = ['Apartment', 'Duplex', 'Semi-detached', 'Land', 'Office', 'Shop', 'Others'];
const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
const str = key => String(body[key] ?? '').trim();
const email = str('email').toLowerCase();
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const fail = error => ({ json: { valid: false, error } });
// The website sends its own address, so links in emails open the site the visitor was on.
const siteUrl = /^https?:\/\/[^\s]+$/.test(str('siteUrl')) ? str('siteUrl').replace(/\/$/, '') : '';

// Step 2: the customer sends back the 6-digit code.
if (str('action') === 'verify') {
  if (!emailOk || !/^\d{6}$/.test(str('code'))) return fail('Enter the 6-digit code from the email.');
  return { json: { valid: true, step: 'verify', email, code: str('code'), config: { ...CONFIG, website: siteUrl || CONFIG.website, sheetGids: SHEET_GIDS } } };
}

// Website server: send one branded email (owner acknowledgement link, invoice, receipt, contact release, team notice).
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
if (str('action') === 'send-email') {
  const list = k => (Array.isArray(body[k]) ? body[k] : []);
  // "team" means the company's own inbox.
  const to = str('to') === 'team' ? CONFIG.teamEmail : str('to');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to) || !str('subject') || !str('heading')) return fail('The email is missing its address, subject or heading.');
  const paragraphs = list('paragraphs').map(p => `<p style='margin:0 0 16px;font-size:16px;line-height:26px;'>${esc(p)}</p>`).join('');
  const rows = list('rows').filter(r => Array.isArray(r) && r[1]).map(([label, value]) => `<tr><td style='padding:12px 16px;border-bottom:1px solid #DCE6DF;'><strong style='display:block;color:#14532D;font-size:12px;line-height:18px;'>${esc(label)}</strong><span style='font-size:16px;line-height:24px;'>${esc(value)}</span></td></tr>`).join('');
  const btns = (Array.isArray(body.buttons) ? body.buttons : body.button ? [body.button] : []).filter(x => x && typeof x === 'object' && /^https?:\/\//.test(String(x.url || ''))).slice(0, 3);
  const html = `<div style='font-family:Arial,Helvetica,sans-serif;color:#24352E;max-width:560px;margin:0 auto;padding:24px;'><p style='margin:0 0 6px;color:#14532D;font-size:13px;font-weight:bold;letter-spacing:1px;'>OLUWASEYI HOMES &amp; PROPERTIES</p><h1 style='margin:0 0 16px;font-size:22px;line-height:30px;'>${esc(str('heading'))}</h1>${paragraphs}${rows ? `<table role='presentation' width='100%' cellspacing='0' cellpadding='0' style='background:#F4F8F5;border-left:4px solid #C5A047;margin:0 0 20px;'>${rows}</table>` : ''}${btns.map(x => `<p style='margin:0 0 12px;'><a href='${esc(x.url)}' style='display:inline-block;padding:14px 22px;background:#14532D;border-radius:6px;color:#FFFFFF;font-size:15px;font-weight:bold;text-decoration:none;'>${esc(x.label || 'Open')}</a></p>`).join('')}${btns.length ? `<p style='margin:8px 0 16px;font-size:13px;line-height:20px;color:#55615A;word-break:break-all;'>If a button does not work, copy this link: ${esc(btns[0].url)}</p>` : ''}<p style='margin:0;font-size:14px;line-height:22px;color:#55615A;'>${esc(str('footnote') || 'Questions? Reply to this email or message us on WhatsApp.')} WhatsApp: <a href='https://wa.me/${CONFIG.whatsapp}' style='color:#163E73;'>+${CONFIG.whatsapp}</a>.</p></div>`;
  return { json: { valid: true, step: 'email', email: to.toLowerCase(), subject: str('subject').slice(0, 200), html } };
}

// Dashboard: send a follow-up for one lead now.
if (str('action') === 'follow-up') {
  if (!/^[0-9a-f-]{36}$/.test(str('leadId'))) return fail('That lead could not be found.');
  return { json: { valid: true, step: 'follow-up', leadId: str('leadId'), actor: str('actor').slice(0, 80) || 'System', siteUrl: /^https?:\/\//.test(str('siteUrl')) ? str('siteUrl').replace(/\/$/, '') : '' } };
}

// Step 1: the enquiry itself.
const pick = (list, value) => list.find(item => item.toLowerCase() === value.toLowerCase());
const enquiryType = pick(Object.keys(SHEET_GIDS), str('enquiryType'));
const propertyType = pick(PROPERTY_TYPES, str('propertyType'));
const errors = [];
if (!str('firstName')) errors.push('firstName is required');
if (!str('lastName')) errors.push('lastName is required');
if (!emailOk) errors.push('email must be a valid email address');
if (!/^\+?[0-9\s()-]{7,20}$/.test(str('phone'))) errors.push('phone must be 7 to 20 digits');
if (!enquiryType) errors.push('enquiryType must be one of: ' + Object.keys(SHEET_GIDS).join(', '));
if (!propertyType) errors.push('propertyType must be one of: ' + PROPERTY_TYPES.join(', '));
if (str('moveInDate') && !/^\d{4}-\d{2}-\d{2}$/.test(str('moveInDate'))) errors.push('moveInDate must be a date (YYYY-MM-DD)');
if (str('inspectionDate') && !/^\d{4}-\d{2}-\d{2}$/.test(str('inspectionDate'))) errors.push('inspectionDate must be a date (YYYY-MM-DD)');
if (str('inspectionSlot') && !['Morning', 'Afternoon', 'Evening'].includes(str('inspectionSlot'))) errors.push('inspectionSlot must be Morning, Afternoon or Evening');
if (str('acknowledged') !== 'yes') errors.push('the customer must acknowledge the introduction');
if (errors.length) return fail(errors.join('; '));
const title = text => text.toLowerCase().replace(/(^|[\s'’-])(\p{L})/gu, (_, sep, letter) => sep + letter.toUpperCase());
const sentence = text => text.replace(/(^|[.!?]\s+|\n+)([^\p{L}\p{N}]*)(\p{L})/gu, (_, boundary, prefix, letter) => boundary + prefix + letter.toUpperCase());
return { json: { valid: true, step: 'request', email, config: { ...CONFIG, website: siteUrl || CONFIG.website, sheetGids: SHEET_GIDS }, payload: {
  fullName: title((str('firstName') + ' ' + str('lastName')).replace(/\s+/g, ' ')),
  phone: str('phone'),
  enquiryType,
  propertyType,
  location: str('location'),
  budget: str('budget'),
  moveInDate: str('moveInDate'),
  inspectionDate: str('inspectionDate'),
  inspectionSlot: str('inspectionSlot'),
  facilities: str('facilities').split(',').map(f => f.trim()).filter(Boolean).slice(0, 20),
  assistance: enquiryType === 'Rent' && str('assistance') === 'yes',
  note: sentence(str('specialRequirement')).slice(0, 1500),
  source: str('source').slice(0, 80) || 'Direct',
  listingId: str('listingId').slice(0, 40),
  acknowledgedAt: $now.toUTC().toISO()
} } };

const lead = $('Prepare lead').first().json.lead;
const GREEN = '#14532D', NAVY = '#163E73', GOLD = '#C5A047';
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const rows = list => list.filter(([, v]) => v && String(v).trim() && v !== 'No Additional Comments').map(([label, v]) => `<tr><td style='padding:14px 18px;border-bottom:1px solid #DCE6DF;overflow-wrap:anywhere;word-break:break-word;'><strong style='display:block;margin-bottom:4px;color:${GREEN};font-size:12px;line-height:18px;'>${esc(label)}</strong><span style='font-size:15px;line-height:24px;'>${esc(v).replace(/\r?\n/g, '<br>')}</span></td></tr>`).join('');
const button = (href, label, bg) => `<tr><td bgcolor='${bg}' style='border-radius:6px;text-align:center;'><a href='${esc(href)}' target='_blank' style='display:inline-block;padding:14px 22px;border:1px solid ${bg};border-radius:6px;color:#FFFFFF;font-size:15px;line-height:22px;font-weight:bold;text-decoration:none;'>${esc(label)}</a></td></tr><tr><td height='12' style='font-size:1px;line-height:12px;'>&nbsp;</td></tr>`;
const layout = o => `<!DOCTYPE html><html lang='en'><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width, initial-scale=1.0'><title>${o.heading}</title></head><body style='margin:0;padding:0;background-color:#F3F6F4;font-family:Arial,Helvetica,sans-serif;color:#24352E;'><div style='display:none;font-size:1px;line-height:1px;max-height:0;max-width:0;overflow:hidden;opacity:0;'>${o.preheader}</div><table role='presentation' width='100%' cellspacing='0' cellpadding='0' border='0' style='background-color:#F3F6F4;'><tr><td align='center' style='padding:24px 12px;'><table role='presentation' width='100%' cellspacing='0' cellpadding='0' border='0' style='max-width:600px;background-color:#FFFFFF;border:1px solid #DCE6DF;'><tr><td style='padding:28px 24px;background-color:${GREEN};border-bottom:5px solid ${GOLD};'><p style='margin:0 0 8px;color:#FDE68A;font-size:12px;line-height:18px;font-weight:bold;letter-spacing:2px;'>OLUWASEYI</p><p style='margin:0;color:#FFFFFF;font-size:22px;line-height:30px;font-weight:bold;'>Homes &amp; Properties</p></td></tr><tr><td style='padding:30px 24px 18px;'><h1 style='margin:0 0 22px;color:${NAVY};font-size:26px;line-height:34px;'>${o.heading}</h1><p style='margin:0 0 14px;font-size:16px;line-height:26px;'>${o.greeting}</p><p style='margin:0;font-size:16px;line-height:26px;'>${o.intro}</p></td></tr>${o.rows ? `<tr><td style='padding:0 24px 24px;'><h2 style='margin:0 0 12px;color:${NAVY};font-size:18px;line-height:26px;'>${o.detailsHeading}</h2><table role='presentation' width='100%' cellspacing='0' cellpadding='0' border='0' style='background-color:#F4F8F5;border-left:4px solid ${GOLD};'>${o.rows}</table></td></tr>` : ''}<tr><td style='padding:0 24px 24px;'><p style='margin:0 0 20px;font-size:16px;line-height:26px;'>${o.action}</p><table role='presentation' cellspacing='0' cellpadding='0' border='0'>${o.buttons}</table><p style='margin:24px 0 0;font-size:15px;line-height:25px;'>Warm regards,<br><strong>Oluwaseyi Homes &amp; Properties</strong></p></td></tr><tr><td style='padding:18px 24px;background-color:#FFF8DB;border-top:1px solid #E6D6A4;'><p style='margin:0;color:#46534B;font-size:12px;line-height:20px;'>${o.footer}<br>WhatsApp: <a href='https://wa.me/${lead.whatsapp}' style='color:${NAVY};text-decoration:underline;'>+${lead.whatsapp}</a></p></td></tr></table></td></tr></table></body></html>`;
const wa = `https://wa.me/${lead.whatsapp}`;
const sheetUrl = `https://docs.google.com/spreadsheets/d/${lead.sheetId}/edit#gid=${lead.sheetGid}`;
const clientHtml = layout({ heading: 'Your enquiry is registered.', preheader: 'Thank you for getting in touch. We will email you the owner\'s contact details once your enquiry is approved.', greeting: `Hello ${esc(lead.fullName.split(' ')[0])},`, intro: 'Thank you for contacting Oluwaseyi Homes &amp; Properties. Your enquiry is registered under the reference below. We review every enquiry. Once yours is approved, we will email you the property owner&#39;s WhatsApp number and email address so you can deal with them directly.', detailsHeading: 'Your enquiry details', rows: rows([['Reference', lead.reference], ['Property', lead.property], ['Phone number', lead.phone], ['Enquiry type', lead.enquiryType], ['Property type', lead.propertyType], ['Preferred location', lead.location], ['Budget', lead.budget], ['Inspection you asked for', lead.inspection], ['Your requirements', lead.clientNote]]), action: 'Would you like to add anything or correct a detail? Reply to this email or message us on WhatsApp.', buttons: button(lead.trackUrl, 'Track your enquiry', GREEN) + button(wa, 'Message us on WhatsApp', NAVY) + button(lead.website, 'Visit our website', NAVY), footer: 'You received this email because you submitted a property enquiry.' });
const teamHtml = layout({ heading: 'New property lead received.', preheader: 'A new property lead is ready for review and follow-up.', greeting: 'Hello Team,', intro: 'A new property enquiry has been received. The customer&#39;s email is verified. Open the dashboard to review the lead and approve it before the owner&#39;s contact is released.', detailsHeading: 'Lead details', rows: rows([['Reference', lead.reference], ['Full name', lead.fullName], ['Email address', lead.email], ['Phone number', lead.phone], ['Enquiry type', lead.enquiryType], ['Property type', lead.propertyType], ['Preferred location', lead.location], ['Budget', lead.budget], ['Special requirements', lead.specialRequirement], ['Received at (Lagos time)', lead.timestamp]]), action: 'Open the lead sheet to review the full client details.', buttons: button(sheetUrl, 'Open the lead sheet', GREEN) + button(lead.website, 'Visit our website', NAVY), footer: 'Internal lead notification for the Oluwaseyi Homes &amp; Properties team.' });
return { json: { clientTo: lead.email, clientSubject: 'We’ve Received Your Property Enquiry - ' + lead.fullName, clientHtml, teamTo: lead.teamEmail, teamSubject: 'New Property Lead Received - ' + lead.enquiryType + ' - ' + lead.fullName, teamHtml } };

// Why Code: shapes the registered lead into the one object the sheet row and both emails read, joining several optional fields into text.
const config = $('Validate and normalize').first().json.config;
const l = $json.lead;
const lagos = $now.setZone('Africa/Lagos');
const asked = [
  l.note,
  l.moveInDate && 'Intended move-in date: ' + l.moveInDate,
  l.facilities && l.facilities.length && 'Essential facilities: ' + l.facilities.join(', '),
  l.assistance && 'Tenant assistance service requested (fee to be agreed before any work starts)',
  l.inspectionDate && 'Inspection requested for ' + l.inspectionDate + (l.inspectionSlot ? ', ' + l.inspectionSlot.toLowerCase() : '')
].filter(Boolean);
const { sheetGids, ...rest } = config;
return { json: { lead: {
  fullName: l.fullName, email: l.email, phone: l.phone, enquiryType: l.enquiryType, propertyType: l.propertyType,
  location: l.location, budget: l.budget,
  clientNote: asked.join('\n'),
  specialRequirement: [...asked, 'Lead ID: ' + l.code, 'Property: ' + (l.property || 'none (general enquiry)'), 'Source: ' + l.source].join('\n'),
  property: l.property || '',
  inspection: l.inspectionDate ? l.inspectionDate + (l.inspectionSlot ? ', ' + l.inspectionSlot.toLowerCase() : '') : '',
  trackToken: l.trackToken,
  trackUrl: config.website + '/track/' + l.trackToken,
  timestamp: lagos.toFormat('dd/MM/yyyy HH:mm:ss'),
  reference: l.code,
  sheetGid: sheetGids[l.enquiryType],
  ...rest
} } };

// Why Code: checks a dozen required fields of different kinds in one place and returns one clear message.
const CONFIG = { teamEmail: 'team@your-domain.example', dashboard: 'https://your-domain.example/admin/submissions', sheetId: 'YOUR_GOOGLE_SHEET_ID', listSheetGid: 'YOUR_LIST_PROPERTY_TAB_GID' };
const p = $json.body && typeof $json.body === 'object' ? $json.body : {};
const text = k => typeof p[k] === 'string' && p[k].trim() !== '';
const errors = [];
if (!['Rent', 'Sell'].includes(p.purpose)) errors.push('purpose must be Rent or Sell');
for (const k of ['fullName', 'phone', 'propertyType', 'address', 'neighbourhood', 'relationship', 'paymentReference', 'agreementVersion', 'feeDue'])
  if (!text(k)) errors.push(k + ' is required');
if (!text('email') || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email)) errors.push('email must be a valid email address');
for (const k of ['askingAmount', 'listingFee', 'feePct', 'protectionMonths'])
  if (typeof p[k] !== 'number' || !(p[k] > 0)) errors.push(k + ' must be a number above zero');
if (!Array.isArray(p.photos) || p.photos.length < 1 || p.photos.length > 8 || p.photos.some(x => typeof x !== 'string')) errors.push('photos must list 1 to 8 stored photos');
if (errors.length) return { json: { valid: false, error: errors.join('; ') } };
return { json: { valid: true, p, config: CONFIG } };

// Why Code: writes the follow-up email for one person, with their own one-time link, for both the daily run and the dashboard button.
const WEBSITE = 'https://your-domain.example';
if (!$json.token) return { json: { skip: true } };
let site = WEBSITE;
// A follow-up started from the dashboard says which website address the link should use.
try { site = $('Validate and normalize').first().json.siteUrl || WEBSITE; } catch (e) {}
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const f = $json;
const deal = f.kind === 'Rent' ? 'rental' : 'sale';
const link = site + '/r/' + f.token;
const other = f.party === 'owner' ? 'the customer we introduced to you' : 'the owner';
const html = `<div style='font-family:Arial,Helvetica,sans-serif;color:#24352E;max-width:560px;margin:0 auto;padding:24px;'><p style='margin:0 0 6px;color:#14532D;font-size:13px;font-weight:bold;letter-spacing:1px;'>OLUWASEYI HOMES &amp; PROPERTIES</p><h1 style='margin:0 0 16px;font-size:22px;line-height:30px;'>How did it go?</h1><p style='margin:0 0 16px;font-size:16px;line-height:26px;'>Hello ${esc(f.party === 'owner' ? f.name : String(f.name).split(' ')[0])}, we put you in touch with ${other} about <strong>${esc(f.property)}</strong> (reference ${esc(f.leadCode)}).</p><p style='margin:0 0 20px;font-size:16px;line-height:26px;'>Please tell us two things: did the inspection take place, and has the ${deal} been completed? It takes less than a minute.</p><p style='margin:0 0 20px;'><a href='${link}' style='display:inline-block;padding:14px 22px;background:#14532D;border-radius:6px;color:#FFFFFF;font-size:15px;font-weight:bold;text-decoration:none;'>Answer two quick questions</a></p><p style='margin:0 0 16px;font-size:13px;line-height:20px;color:#55615A;word-break:break-all;'>If the button does not work, copy this link: ${link}</p><p style='margin:0;font-size:14px;line-height:22px;color:#55615A;'>The link works once, for 48 hours, and is only for you.</p></div>`;
return { json: { to: f.email, subject: 'A quick question about ' + f.property, html } };
